import { FileBlob } from "../shared/file-blob.mjs";
import { OfficeKitCodecError } from "./office-kit-error.mjs";
import {
  isJavaScriptMemoryAllocationError,
  javaScriptMemoryBudgetError,
  OFFICE_KIT_DEFAULT_MAX_INPUT_BYTES,
} from "./office-kit-memory.mjs";
import {
  OFFICE_KIT_NATIVE_TRANSPORT_VERSION,
  startOfficeKitNativeClient,
} from "./office-kit-native-client.mjs";

export const OFFICE_KIT_PROTOCOL_VERSION = 2;

const runtimeStates = Object.freeze({
  office: { promise: undefined, invocationTail: Promise.resolve() },
  ppj: { promise: undefined, invocationTail: Promise.resolve() },
});

async function runtime(profile) {
  const state = runtimeStates[profile];
  if (!state) throw new TypeError(`Unknown OfficeKit native codec profile ${profile}.`);
  while (true) {
    if (!state.promise) {
      state.promise = startOfficeKitNativeClient({ profile })
        .catch((error) => {
          state.promise = undefined;
          if (error instanceof OfficeKitCodecError) throw error;
          throw new OfficeKitCodecError("Bundled OfficeKit NativeAOT Codec could not be loaded.", [], { code: "runtime_unavailable", cause: error });
        });
    }
    const loadedPromise = state.promise;
    const loaded = await loadedPromise;
    if (loaded.tryAcquire()) return loaded;
    if (state.promise === loadedPromise) state.promise = undefined;
  }
}

function uint64(value, name) {
  if (value == null) return 0n;
  if (typeof value === "bigint") {
    if (value < 0n) throw new TypeError(`${name} must be a non-negative integer.`);
    return value;
  }
  if (!Number.isSafeInteger(value) || value < 0) throw new TypeError(`${name} must be a non-negative safe integer or bigint.`);
  return BigInt(value);
}

export function uint32(value, name) {
  if (value == null) return 0;
  if (!Number.isInteger(value) || value < 0 || value > 0xffff_ffff) throw new TypeError(`${name} must be an unsigned 32-bit integer.`);
  return value;
}

export function codecLimits(limits = {}) {
  return {
    maxInputBytes: uint64(limits.maxInputBytes, "maxInputBytes"),
    maxUncompressedBytes: uint64(limits.maxUncompressedBytes, "maxUncompressedBytes"),
    maxParts: uint32(limits.maxParts, "maxParts"),
    maxSheets: uint32(limits.maxSheets, "maxSheets"),
    maxCells: uint64(limits.maxCells, "maxCells"),
    maxCompressionRatio: uint32(limits.maxCompressionRatio, "maxCompressionRatio"),
  };
}

function bytesFrom(value) {
  if (value instanceof Uint8Array) {
    return value.constructor === Uint8Array
      ? value
      : new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
  }
  if (ArrayBuffer.isView(value)) return new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
  if (value instanceof ArrayBuffer) return new Uint8Array(value);
  throw new TypeError("Expected FileBlob, Uint8Array, ArrayBuffer, or ArrayBuffer view.");
}

export async function inputBytes(value) {
  if (value instanceof FileBlob) return bytesFrom(value.bytes);
  return bytesFrom(value);
}

function effectiveMaxInputBytes(limits = {}) {
  const normalized = codecLimits(limits);
  return normalized.maxInputBytes > 0n ? normalized.maxInputBytes : OFFICE_KIT_DEFAULT_MAX_INPUT_BYTES;
}

export function assertOfficeKitInputBudget(value, limits = {}, family = "Office") {
  const bytes = bytesFrom(value);
  const maximum = effectiveMaxInputBytes(limits);
  if (BigInt(bytes.byteLength) > maximum) {
    throw new OfficeKitCodecError(
      `${family} input has ${bytes.byteLength} bytes and exceeds max_input_bytes (${maximum}).`,
      [],
      { code: "input_budget_exceeded" },
    );
  }
  return bytes;
}

export async function boundedInputBytes(value, limits = {}, family = "Office") {
  return assertOfficeKitInputBudget(await inputBytes(value), limits, family);
}

export async function ownedInputBytes(value, limits = {}, family = "Office") {
  const bytes = await boundedInputBytes(value, limits, family);
  try {
    return Uint8Array.from(bytes);
  } catch (error) {
    if (isJavaScriptMemoryAllocationError(error) || error instanceof RangeError) {
      throw javaScriptMemoryBudgetError(`${family} source ownership`, error);
    }
    throw error;
  }
}

function responseFailure(response) {
  const message = response.diagnostics.length
    ? response.diagnostics.map((item) => `${item.code}: ${item.message}`).join("\n")
    : "OfficeKit codec returned an unspecified failure.";
  return new OfficeKitCodecError(message, response.diagnostics);
}

async function invokeOfficeKitExclusive(profile, request, { fileSidecar = false, consumeResponse } = {}) {
  if (request?.file?.byteLength) assertOfficeKitInputBudget(request.file, request.limits, "Office");
  const state = runtimeStates[profile];
  const loaded = await runtime(profile);
  const loadedPromise = state.promise;
  let response;
  let stage = "request encoding";
  try {
    const sidecar = fileSidecar && request.file?.byteLength ? bytesFrom(request.file) : undefined;
    let wireRequestBytes;
    let decodeResponse;
    if (profile === "ppj") {
      const wire = await import("./office-kit-ppj-wire.mjs");
      wireRequestBytes = wire.encodePpjCodecRequest(request, { omitFile: sidecar != null });
      decodeResponse = wire.decodePpjCodecResponse;
    } else {
      const [{ create, fromBinary, toBinary }, { CodecRequestSchema, CodecResponseSchema }] = await Promise.all([
        import("@bufbuild/protobuf"),
        import("../generated/office_kit/artifact/v1/office_artifact_pb.js"),
      ]);
      const wireRequest = create(CodecRequestSchema, request);
      if (sidecar) wireRequest.file = new Uint8Array();
      wireRequestBytes = toBinary(CodecRequestSchema, wireRequest);
      decodeResponse = (bytes) => fromBinary(CodecResponseSchema, bytes);
    }
    stage = "response decoding";
    const wireResponse = bytesFrom(await loaded.invoke(wireRequestBytes, sidecar));
    response = decodeResponse(wireResponse);
  } catch (error) {
    loaded.kill();
    if (state.promise === loadedPromise) state.promise = undefined;
    if (error instanceof OfficeKitCodecError) throw error;
    if (isJavaScriptMemoryAllocationError(error)) throw javaScriptMemoryBudgetError(stage, error);
    throw new OfficeKitCodecError("OfficeKit native codec returned an invalid protobuf response.", [], { code: "runtime_protocol_mismatch", cause: error });
  } finally {
    loaded.release();
  }
  if (!response.ok) throw responseFailure(response);
  if (typeof consumeResponse === "function") {
    try {
      return await consumeResponse(response);
    } catch (error) {
      if (isJavaScriptMemoryAllocationError(error)) throw javaScriptMemoryBudgetError("artifact hydration", error);
      throw error;
    }
  }
  return response;
}

function assertOfficeKitRequest(request) {
  if (Object.hasOwn(request || {}, "allowLossy") || Object.hasOwn(request || {}, "allow_lossy")) {
    throw new TypeError("invokeOfficeKit no longer accepts allowLossy/allow_lossy; opaque Office content without a validated source package always fails closed.");
  }
  if (request?.file?.byteLength) assertOfficeKitInputBudget(request.file, request.limits, "Office");
}

async function invokeProfileLazy(profile, createRequest, options = {}) {
  if (typeof createRequest !== "function") throw new TypeError("invokeOfficeKitLazy expects a request factory.");
  const state = runtimeStates[profile];
  const invokeCreatedRequest = () => {
    let request;
    try {
      request = createRequest();
    } catch (error) {
      if (isJavaScriptMemoryAllocationError(error)) throw javaScriptMemoryBudgetError("request construction", error);
      throw error;
    }
    assertOfficeKitRequest(request);
    return invokeOfficeKitExclusive(profile, request, options);
  };
  const operation = state.invocationTail.then(
    invokeCreatedRequest,
    invokeCreatedRequest,
  );
  // Never retain the most recent protobuf response through the queue tail.
  state.invocationTail = operation.then(() => undefined, () => undefined);
  return operation;
}

export async function invokeOfficeKitLazy(createRequest, options = {}) {
  return invokeProfileLazy("office", createRequest, options);
}

export async function invokeOfficeKitPpjLazy(createRequest, options = {}) {
  return invokeProfileLazy("ppj", createRequest, options);
}

export async function invokeOfficeKit(request, options = {}) {
  assertOfficeKitRequest(request);
  return invokeOfficeKitLazy(() => request, options);
}

export function assertCodecOptions(options, allowed, apiName) {
  if (options == null || typeof options !== "object" || Array.isArray(options)) throw new TypeError(`${apiName} options must be an object.`);
  const unsupported = Object.keys(options).filter((key) => !allowed.has(key));
  if (unsupported.length) throw new TypeError(`${apiName} does not accept option${unsupported.length === 1 ? "" : "s"} ${unsupported.join(", ")}. OfficeKit is the only Office codec and lossy fallback is unavailable.`);
}

export async function officeKitStatus() {
  const [office, ppj] = await Promise.all([runtime("office"), runtime("ppj")]);
  try {
    return {
      available: true,
      protocolVersion: OFFICE_KIT_PROTOCOL_VERSION,
      assemblyName: office.descriptor.assemblyName,
      backend: "native-aot",
      target: office.descriptor.target,
      transportVersion: OFFICE_KIT_NATIVE_TRANSPORT_VERSION,
      manifest: office.descriptor.manifest,
      profiles: Object.freeze({
        office: Object.freeze({ assemblyName: office.descriptor.assemblyName }),
        ppj: Object.freeze({ assemblyName: ppj.descriptor.assemblyName }),
      }),
    };
  } finally {
    office.release();
    ppj.release();
  }
}

---NATIVE CLIENT---
import { createHash } from "node:crypto";
import { createReadStream } from "node:fs";
import { lstat, readFile } from "node:fs/promises";
import { spawn } from "node:child_process";
import { once } from "node:events";
import { createRequire } from "node:module";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

import { OfficeKitCodecError } from "./office-kit-error.mjs";
import { isJavaScriptMemoryAllocationError, javaScriptMemoryBudgetError } from "./office-kit-memory.mjs";

export const OFFICE_KIT_NATIVE_TRANSPORT_VERSION = 2;
export const OFFICE_KIT_NATIVE_MAX_FRAME_BYTES = 128 * 1024 * 1024;

const HANDSHAKE_BYTES = 12;
const HANDSHAKE_MAGIC = Buffer.from("OKIT", "ascii");
const REQUEST_PREFIX_BYTES = 8;
const DEFAULT_IDLE_RETIRE_MS = 1_000;
const STDERR_LIMIT = 16 * 1024;
const require = createRequire(import.meta.url);
const activeClients = new Set();

const NATIVE_PROFILES = Object.freeze({
  office: Object.freeze({ assemblyName: "officekit-codec", executable: "officekit-codec" }),
  ppj: Object.freeze({ assemblyName: "officekit-ppj-codec", executable: "officekit-ppj-codec" }),
});

const PLATFORM_PACKAGES = Object.freeze({
  "darwin-arm64": Object.freeze({
    name: "office-kit-codec-darwin-arm64",
    os: "darwin",
    cpu: "arm64",
  }),
  "linux-x64": Object.freeze({
    name: "office-kit-codec-linux-x64",
    os: "linux",
    cpu: "x64",
  }),
  "win32-x64": Object.freeze({
    name: "office-kit-codec-win32-x64",
    os: "win32",
    cpu: "x64",
  }),
});

let exitHookInstalled = false;

export function officeKitNativeTarget(platform = process.platform, arch = process.arch) {
  const target = `${platform}-${arch}`;
  if (!PLATFORM_PACKAGES[target]) {
    throw nativeError("runtime_unsupported_platform", `OfficeKit NativeAOT Codec does not support ${target}.`);
  }
  return target;
}

export async function loadOfficeKitNativeDescriptor({
  platform = process.platform,
  arch = process.arch,
  packageJsonPath: suppliedPackageJsonPath,
  profile = "office",
  requiredCapability,
} = {}) {
  const target = officeKitNativeTarget(platform, arch);
  const expected = PLATFORM_PACKAGES[target];
  const expectedProfile = NATIVE_PROFILES[profile];
  if (!expectedProfile) throw new TypeError(`Unknown OfficeKit native codec profile ${profile}.`);
  const packageJsonPath = suppliedPackageJsonPath ?? await resolvePlatformPackageJson(expected.name);
  const packageRoot = path.dirname(packageJsonPath);
  const [packageMetadata, manifest] = await Promise.all([
    readJson(packageJsonPath, "native codec package metadata"),
    readJson(path.join(packageRoot, "manifest.json"), "native codec manifest"),
  ]);
  const rootMetadata = await readJson(new URL("../../package.json", import.meta.url), "OfficeKit package metadata");

  if (packageMetadata.name !== expected.name || packageMetadata.version !== rootMetadata.version) {
    throw nativeError("runtime_identity_mismatch", `OfficeKit requires ${expected.name}@${rootMetadata.version}.`);
  }
  if (!packageMetadata.os?.includes(expected.os) || !packageMetadata.cpu?.includes(expected.cpu)) {
    throw nativeError("runtime_identity_mismatch", `Native codec package ${expected.name} does not declare ${target}.`);
  }
  if (manifest.schemaVersion !== 2 || manifest.backend !== "native-aot" || manifest.target !== target ||
      manifest.transportVersion !== OFFICE_KIT_NATIVE_TRANSPORT_VERSION || manifest.protocolVersion !== 2 ||
      manifest.packageVersion !== rootMetadata.version) {
    throw nativeError("runtime_identity_mismatch", `Native codec manifest for ${target} is incompatible with this OfficeKit package.`);
  }

  const profileManifest = manifest.profiles?.[profile];
  const executableName = platform === "win32" ? `${expectedProfile.executable}.exe` : expectedProfile.executable;
  const relativeExecutable = `bin/${executableName}`;
  if (profileManifest?.assemblyName !== expectedProfile.assemblyName || profileManifest?.executable !== relativeExecutable) {
    throw nativeError("runtime_identity_mismatch", `Native codec manifest does not contain the expected ${profile} profile for ${target}.`);
  }
  if (requiredCapability && profileManifest?.[requiredCapability] !== true) return null;
  const executablePath = path.join(packageRoot, relativeExecutable);
  const executableRecord = manifest.files?.find((item) => item.path === relativeExecutable);
  if (!executableRecord || !Number.isSafeInteger(executableRecord.bytes) || executableRecord.bytes <= 0 ||
      !/^[a-f0-9]{64}$/u.test(executableRecord.sha256 || "")) {
    throw nativeError("runtime_identity_mismatch", `Native codec manifest does not contain a valid ${relativeExecutable} record.`);
  }
  const descriptor = await lstat(executablePath).catch((error) => {
    if (error?.code === "ENOENT") return null;
    throw error;
  });
  if (!descriptor?.isFile() || descriptor.isSymbolicLink() || descriptor.size !== executableRecord.bytes) {
    throw nativeError("runtime_integrity_failure", `Native codec executable is missing or has the wrong size for ${target}.`);
  }
  if (platform !== "win32" && (descriptor.mode & 0o111) === 0) {
    throw nativeError("runtime_integrity_failure", `Native codec executable is not executable for ${target}.`);
  }
  const actualHash = await sha256File(executablePath);
  if (actualHash !== executableRecord.sha256) {
    throw nativeError("runtime_integrity_failure", `Native codec executable failed SHA-256 verification for ${target}.`);
  }
  return Object.freeze({
    target,
    profile,
    packageName: expected.name,
    packageRoot,
    executablePath,
    assemblyName: profileManifest.assemblyName,
    manifest,
  });
}

export async function startOfficeKitNativeClient(options = {}) {
  const descriptor = options.descriptor ?? await loadOfficeKitNativeDescriptor(options);
  return NativeCodecClient.start(descriptor, options);
}

class NativeCodecClient {
  static async start(descriptor, { spawnProcess = spawn, idleRetireMs = DEFAULT_IDLE_RETIRE_MS } = {}) {
    const child = spawnProcess(descriptor.executablePath, ["--serve"], {
      cwd: descriptor.packageRoot,
      env: { ...process.env, DOTNET_GCConserveMemory: "9" },
      shell: false,
      stdio: ["pipe", "pipe", "pipe"],
      windowsHide: true,
    });
    const client = new NativeCodecClient(child, descriptor, idleRetireMs);
    try {
      await client.initialize();
      activeClients.add(client);
      installExitHook();
      return client;
    } catch (error) {
      client.kill();
      throw error;
    }
  }

  constructor(child, descriptor, idleRetireMs) {
    this.child = child;
    this.descriptor = descriptor;
    this.reader = new ExactReader(child.stdout);
    this.queue = Promise.resolve();
    this.pendingRequests = 0;
    this.idleRetireMs = idleRetireMs;
    this.idleTimer = undefined;
    this.retiring = false;
    this.stderr = Buffer.alloc(0);
    this.closed = false;
    this.terminated = new Promise((resolve) => {
      let settled = false;
      const finish = (value) => {
        if (settled) return;
        settled = true;
        this.closed = true;
        activeClients.delete(this);
        resolve(value);
      };
      child.once("error", (error) => finish({ error }));
      child.once("exit", (code, signal) => finish({ code, signal }));
    });
    child.stderr.on("data", (chunk) => {
      if (this.stderr.length >= STDERR_LIMIT) return;
      const bytes = Buffer.from(chunk);
      const remaining = STDERR_LIMIT - this.stderr.length;
      this.stderr = Buffer.concat([this.stderr, bytes.subarray(0, remaining)]);
    });
  }

  async initialize() {
    const handshake = await this.readOrThrow(HANDSHAKE_BYTES, "runtime_start_failed");
    if (!handshake.subarray(0, 4).equals(HANDSHAKE_MAGIC)) {
      throw nativeError("runtime_protocol_mismatch", "OfficeKit native codec returned an invalid handshake.");
    }
    const transportVersion = handshake.readUInt32BE(4);
    const protocolVersion = handshake.readUInt32BE(8);
    if (transportVersion !== OFFICE_KIT_NATIVE_TRANSPORT_VERSION || protocolVersion !== 2) {
      throw nativeError(
        "runtime_protocol_mismatch",
        `OfficeKit native codec handshake reported transport ${transportVersion} and protocol ${protocolVersion}.`,
      );
    }
    this.unref();
    this.release();
  }

  invoke(bytes, fileBytes = undefined) {
    if (!(bytes instanceof Uint8Array)) throw new TypeError("OfficeKit native codec request must be a Uint8Array.");
    if (fileBytes != null && !(fileBytes instanceof Uint8Array)) {
      throw new TypeError("OfficeKit native codec file sidecar must be a Uint8Array.");
    }
    const fileLength = fileBytes?.byteLength ?? 0;
    if (bytes.byteLength === 0 || bytes.byteLength + fileLength > OFFICE_KIT_NATIVE_MAX_FRAME_BYTES) {
      throw nativeError("request_budget_exceeded", `OfficeKit native codec request and file sidecar exceed the ${OFFICE_KIT_NATIVE_MAX_FRAME_BYTES}-byte transport budget.`);
    }
    if (!this.tryAcquire()) throw this.terminationError();
    this.pendingRequests += 1;
    if (this.pendingRequests === 1) this.ref();
    const operation = this.queue.then(
      () => this.invokeFrame(bytes, fileBytes),
      () => this.invokeFrame(bytes, fileBytes),
    );
    // A successful Promise retains its fulfillment value. Store a void tail so
    // an idle client cannot pin the most recent response frame indefinitely.
    this.queue = operation.then(() => undefined, () => undefined);
    return operation.finally(() => {
      this.pendingRequests -= 1;
      if (this.pendingRequests === 0) {
        this.unref();
        this.release();
      }
    });
  }

  async invokeFrame(bytes, fileBytes) {
    if (this.closed) throw this.terminationError();
    const prefix = Buffer.allocUnsafe(REQUEST_PREFIX_BYTES);
    prefix.writeUInt32BE(bytes.byteLength, 0);
    prefix.writeUInt32BE(fileBytes?.byteLength ?? 0, 4);
    await this.writeFrame(prefix, bytes, fileBytes);
    const responsePrefix = await this.readOrThrow(4, "runtime_terminated");
    const responseLength = responsePrefix.readUInt32BE(0);
    if (responseLength === 0 || responseLength > OFFICE_KIT_NATIVE_MAX_FRAME_BYTES) {
      throw nativeError("runtime_protocol_mismatch", "OfficeKit native codec returned an invalid response frame length.");
    }
    return this.readOrThrow(responseLength, "runtime_terminated");
  }

  async writeFrame(prefix, bytes, fileBytes) {
    if (this.closed || this.child.stdin.destroyed) throw this.terminationError();
    this.child.stdin.cork();
    let prefixAccepted;
    let requestAccepted;
    let fileAccepted = true;
    try {
      prefixAccepted = this.child.stdin.write(prefix);
      requestAccepted = this.child.stdin.write(bytes);
      if (fileBytes?.byteLength) fileAccepted = this.child.stdin.write(fileBytes);
    } finally {
      this.child.stdin.uncork();
    }
    if (!prefixAccepted || !requestAccepted || !fileAccepted) {
      await Promise.race([
        once(this.child.stdin, "drain"),
        this.terminated.then(() => { throw this.terminationError(); }),
      ]);
    }
  }

  async readOrThrow(length, code) {
    try {
      return await Promise.race([
        this.reader.readExactly(length),
        this.terminated.then(() => { throw this.terminationError(code); }),
      ]);
    } catch (error) {
      if (error instanceof OfficeKitCodecError) throw error;
      if (isJavaScriptMemoryAllocationError(error)) throw javaScriptMemoryBudgetError("native response buffering", error);
      throw nativeError(code, "OfficeKit native codec closed its response stream unexpectedly.", error);
    }
  }

  terminationError(code = "runtime_terminated") {
    const detail = this.stderr.toString("utf8").trim();
    return nativeError(code, `OfficeKit native codec terminated unexpectedly${detail ? `: ${detail}` : "."}`);
  }

  ref() {
