export const PPJ_USAGE = `Usage:
  officekit ppj resume <task-id> -o <deck.ppj> [--json]
  officekit ppj import <input.pptx> -o <deck.ppj> [--task <id>] [--json]
  officekit ppj inspect <deck.ppj> [--query <text>] [--page <id>] [--json]
